"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { ChevronLeft, ChevronRight, X } from "lucide-react";
import {
  planTutorials,
  type TutorialStep,
} from "@/components/tutorial-content";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { TutorialHint } from "@/components/tutorial-hint";

function reducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function TutorialDialog({
  steps,
  onClose,
  draft = false,
}: {
  steps: readonly TutorialStep[];
  onClose: () => void;
  draft?: boolean;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const next = useRef<HTMLButtonElement>(null);
  const done = useRef<HTMLButtonElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const busy = useRef(false);
  const closing = useRef(false);
  const [index, setIndex] = useState(0);
  const [phase, setPhase] = useState<"idle" | "out" | "in" | "closing">("idle");
  const [direction, setDirection] = useState(1);
  const titleId = useId();
  const last = index === steps.length - 1;

  useEffect(() => {
    const element = dialog.current!;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    element.showModal();
    (next.current ?? done.current)?.focus();
    return () => {
      clearTimeout(timer.current);
      element.close();
      document.body.style.overflow = previousOverflow;
    };
  }, []);

  useEffect(() => {
    // Next is replaced by Done, so preserve focus when its node disappears.
    if (last && document.activeElement === document.body) done.current?.focus();
  }, [last]);

  const close = useCallback(() => {
    if (closing.current) return;
    closing.current = true;
    clearTimeout(timer.current);
    if (reducedMotion()) {
      dialog.current?.close();
      onClose();
    } else {
      setPhase("closing");
      timer.current = setTimeout(() => {
        dialog.current?.close();
        onClose();
      }, 200);
    }
  }, [onClose]);

  function travel(delta: number) {
    if (
      busy.current ||
      closing.current ||
      index + delta < 0 ||
      index + delta >= steps.length
    )
      return;
    const focusNext = document.activeElement === next.current;
    const arrive = () => {
      setIndex(index + delta);
      // Focus after React commits the final-step button replacement.
      if (focusNext && index + delta === steps.length - 1) {
        requestAnimationFrame(() => done.current?.focus());
      }
    };
    if (reducedMotion()) {
      arrive();
      return;
    }
    busy.current = true;
    setDirection(delta);
    setPhase("out");
    timer.current = setTimeout(() => {
      arrive();
      setPhase("in");
      timer.current = setTimeout(() => {
        busy.current = false;
        setPhase("idle");
      }, 240);
    }, 150);
  }

  const step = steps[index];
  return (
    <dialog
      ref={dialog}
      className="tutorial-dialog"
      data-phase={phase}
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      onCancel={(event) => {
        event.preventDefault();
        close();
      }}
      onClick={(event) => {
        if (event.target === event.currentTarget) close();
      }}
      onKeyDown=[REDACTED_SECRET]
        if (event.key === "Tab") {
          const controls = Array.from(
            event.currentTarget.querySelectorAll<HTMLButtonElement>(
              "button:not(:disabled)",
            ),
          );
          const first = controls[0];
          const final = controls[controls.length - 1];
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            final?.focus();
          } else if (!event.shiftKey && document.activeElement === final) {
            event.preventDefault();
            first?.focus();
          }
        }
        if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
          event.preventDefault();
          travel(event.key === "ArrowRight" ? 1 : -1);
        }
      }}
    >
      <div
        className="tutorial-card relative [flex:0_0_auto] w-[min(480px,_100%)] m-auto [border:1px_solid_var(--border)] rounded-[20px] [background:var(--card)] text-foreground shadow-[0_24px_80px_var(--color-globals-box-shadow-59)]"
        data-phase={phase}
      >
        <header className="tutorial-topbar flex items-center justify-between py-3 px-4">
          <span
            className="tutorial-counter text-[12px] font-medium text-body [font-variant-numeric:tabular-nums]"
            aria-live="polite"
            aria-atomic="true"
          >
            {index + 1} / {steps.length}
          </span>
          <button
            type="button"
            className="tutorial-close grid place-items-center w-9.5 h-9.5 rounded-[50%] cursor-pointer"
            aria-label="Close tutorial"
            onClick={close}
          >
            <X size={18} aria-hidden="true" />
          </button>
        </header>
        <div
          className="tutorial-progress h-[3px] overflow-hidden [background:var(--accent-soft)]"
          aria-hidden="true"
        >
          <span
            style={{ transform: `scaleX(${(index + 1) / steps.length})` }}
          />
        </div>
        <div className="tutorial-body relative overflow-hidden [padding:28px_60px_22px]">
          <button
            type="button"
            className="tutorial-arrow absolute z-[1] [top:calc(50%_-_19px)] grid place-items-center w-9.5 h-9.5 p-0 [border:1px_solid_var(--border)] rounded-[50%] [background:var(--surface)] text-foreground cursor-pointer disabled:opacity-[0.4] disabled:cursor-default tutorial-back left-2.5"
            aria-label="Back"
            disabled={index === 0}
            onClick={() => travel(-1)}
          >
            <ChevronLeft size={20} aria-hidden="true" />
          </button>
          <div
            key={index}
            className={`tutorial-step min-w-0 ${phase === "out" ? "step-out" : phase === "in" ? "step-in" : ""}`}
            style={{ "--travel": direction } as React.CSSProperties}
          >
            <h2
              id={titleId}
              className="tutorial-title text-[22px] leading-[1.25] font-bold tracking-[-0.03em] wrap-anywhere"
            >
              {step.title}
            </h2>
            <p className="tutorial-text mt-3 text-[14px] leading-[1.6] text-body wrap-anywhere">
              {step.text}
            </p>
            <div className="tutorial-visual mt-5.5">
              <TutorialHint hint={step.hint} draft={draft} />
            </div>
          </div>
          {!last && (
            <button
              ref={next}
              type="button"
              className="tutorial-arrow absolute z-[1] [top:calc(50%_-_19px)] grid place-items-center w-9.5 h-9.5 p-0 [border:1px_solid_var(--border)] rounded-[50%] [background:var(--surface)] text-foreground cursor-pointer disabled:opacity-[0.4] disabled:cursor-default tutorial-next right-2.5"
              aria-label="Next"
              onClick={() => travel(1)}
            >
              <ChevronRight size={20} aria-hidden="true" />
            </button>
          )}
        </div>
        <footer className="tutorial-footer relative flex items-center justify-center min-h-17.5 py-3.5 px-4 border-t border-dotted border-separator">
          <div
            className="tutorial-dots flex items-center gap-0"
            aria-hidden="true"
          >
            {steps.map((_, i) => (
              <span className="tutorial-dot-slot block w-4.5 h-1.5" key={i}>
                <span className={i === index ? "is-active" : ""} />
              </span>
            ))}
          </div>
          {last && (
            <button
              ref={done}
              type="button"
              className="tutorial-done absolute right-4 py-[9px] px-4 [border:1px_solid_var(--border)] rounded-[12px] [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] text-[14px] font-semibold cursor-pointer primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none"
              onClick={close}
            >
              Done
            </button>
          )}
        </footer>
      </div>
    </dialog>
  );
}

export function HelpTutorial() {
  const pathname = usePathname();
  const [state, setState] = useState({ pathname, open: false });
  const [visibility, setVisibility] = useState<
    "visible" | "dismissing" | "dismissed"
  >("visible");
  const dismissing = useRef(false);
  const dismissalTimer = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined,
  );

  useEffect(() => () => clearTimeout(dismissalTimer.current), []);

  useEffect(() => {
    if (visibility === "dismissed") {
      document.getElementById("main-content")?.focus({ preventScroll: true });
    }
  }, [visibility]);

  function dismiss() {
    if (dismissing.current) return;
    dismissing.current = true;
    if (reducedMotion()) {
      setVisibility("dismissed");
    } else {
      setVisibility("dismissing");
      dismissalTimer.current = setTimeout(
        () => setVisibility("dismissed"),
        200,
      );
    }
  }
  const launcher = useRef<HTMLButtonElement>(null);
  const restoreLauncherFocus = useRef(false);
  if (state.pathname !== pathname) setState({ pathname, open: false });
  const open = state.pathname === pathname && state.open;
  useEffect(() => {
    // Wait until React removes the dialog and unhides the launcher. A frame
    // scheduled from the closing timer can run before that commit.
    if (!open && restoreLauncherFocus.current) {
      restoreLauncherFocus.current = false;
      launcher.current?.focus();
    }
  }, [open]);
  const access = useWorkspaceEntitlements();
  const steps = planTutorials(pathname, access);
  const close = useCallback(() => {
    restoreLauncherFocus.current = true;
    setState({ pathname, open: false });
  }, [pathname]);
  if (!steps || visibility === "dismissed") return null;

  return (
    <>
      <div
        className="help-launcher fixed z-[90] w-11 h-11 [right:max(20px,_env(safe-area-inset-right))] [bottom:max(20px,_env(safe-area-inset-bottom))] [&[hidden]]:hidden [&[data-state='dismissing']]:opacity-[0] [&[data-state='dismissing']]:pointer-events-none"
        data-state={visibility}
        hidden={open}
        inert={visibility === "dismissing"}
      >
        <div className="help-cloud-visibility absolute right-0 bottom-17.5 w-max pointer-events-none">
          <div className="help-cloud-entrance">
            <div
              className="help-cloud relative py-[7px] px-3.5 [border:1px_solid_var(--border)] rounded-full [background:var(--surface)] text-foreground text-[12.5px] font-medium leading-normal"
              aria-hidden="true"
            >
              Need help?
            </div>
          </div>
        </div>
        <div className="help-button-pop relative">
          <button
            ref={launcher}
            type="button"
            className="help-button relative grid place-items-center w-11 h-11 p-0 [border:1px_solid_color-mix(in_srgb,_var(--accent)_65%,_var(--color-globals-white))] rounded-[50%] [background:var(--accent)] text-primary-foreground text-[18px] font-bold cursor-pointer shadow-[0_10px_28px_color-mix(in_srgb,_var(--accent)_45%,_transparent)]"
            aria-label={`Help with ${pathname.slice(1)}`}
            aria-haspopup="dialog"
            onClick={() => {
              if (!dismissing.current) setState({ pathname, open: true });
            }}
          >
            ?
          </button>
        </div>
        {!open && (
          <button
            type="button"
            className="help-dismiss absolute top-[-6px] left-[-6px] z-[1] grid place-items-center w-5 h-5 p-0 [border:1px_solid_var(--border)] rounded-[50%] [background:var(--surface)] text-body shadow-[0_2px_6px_var(--color-globals-box-shadow-57)] cursor-pointer css-hover:text-foreground"
            aria-label="Hide help button until reload."
            title="Hide help button until reload."
            onClick={dismiss}
          >
            <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
              <line x1="2" y1="2" x2="8" y2="8" />
              <line x1="8" y1="2" x2="2" y2="8" />
            </svg>
          </button>
        )}
      </div>
      {open && (
        <TutorialDialog
          steps={steps}
          onClose={close}
          draft={pathname === "/compose"}
        />
      )}
    </>
  );
}
